insert into public.suppliers (id, data, published, status) values ('s1', '{"id":"s1","name":"بوارق لتجهيز المناسبات","city":"الرياض","area":"يغطي كل مناطق المملكة","featured":true,"cats":["kosha","tents","photo","av","live","hosp","power","stage"],"photos":["media:s1","media:s7","media:s4","media:s3","media:s5"],"hue":18,"tags":["تجهيز متكامل","فريق ميداني","بث مباشر"],"about":"نوفر خدمات تنسيق وتجهيز قاعات الأفراح والمناسبات بأعلى مستوى من الاحترافية: الكوشة والطاولات الرجالية، الخيام والسجاد والطاولات، استديو التصوير، السماعات والشاشات والإضاءة، البث المباشر، المفروشات والضيافة، مولدات الكهرباء، والاستيدج وتجهيز المسرح. تجهيز متكامل لجميع المناسبات والأفراح، مع الاهتمام بأدق التفاصيل.","packages":[{"id":"p1","name":"باقة الملكة","items":["كوشة نصف دائرية","إضاءة دافئة","مصور فوتوغرافي 4 ساعات","ضيافة قهوة وتمر"]},{"id":"p2","name":"باقة الفرح المتكامل","items":["كوشة رئيسية وطاولات رجالية","صوتيات وشاشتين LED","استديو تصوير وفيديو","بث مباشر للأهل","مولد احتياطي"]},{"id":"p3","name":"باقة القصر","items":["استيدج ومسرح مخصص","خيمة رجال وسجاد","إضاءة معمارية متحركة","فريق تصوير كامل ودرون","ضيافة فاخرة وصبابين","مولدين وفني طوال الحفل"]}]}'::jsonb, true, 'active') on conflict (id) do nothing;
